import asyncio
import json
import gel

async def main():
    client = gel.create_async_client()

    # 1. Delete existing data
    await client.execute("""
        delete Batch;
        delete Certificate;
        delete Measurement;
        delete Sample;
    """)
    print("Deleted existing data.")

    # 2. Insert 4 samples in one single statement
    batch_data = [
        {"label": "Alpha-01", "grams": 1.5},
        {"label": "Bravo-02", "grams": 2.25},
        {"label": "Charlie-03", "grams": 3.00},
        {"label": "Delta-04", "grams": 4.75}
    ]
    inserted_batch = await client.query("""
        with data := <json>$data
        for item in json_array_unpack(data) union (
            insert Sample {
                label := <str>item['label'],
                grams := <float64>item['grams']
            }
        ) {
            label,
            intake_ref,
            intake_at,
            label_key,
            age,
            assay_count,
            measurement_count,
            total_value
        }
    """, data=json.dumps(batch_data))

    print("Inserted batch:")
    for s in inserted_batch:
        print(f"  {s.label}: ref={s.intake_ref}, at={s.intake_at}")

    # 3. Insert Echo-05 in a later, separate statement
    echo_sample = await client.query_single("""
        insert Sample {
            label := 'Echo-05',
            grams := 5.5
        } {
            label,
            intake_ref,
            intake_at,
            label_key,
            age,
            assay_count,
            measurement_count,
            total_value
        }
    """)
    print(f"Inserted Echo-05: ref={echo_sample.intake_ref}, at={echo_sample.intake_at}")

    # 4. Query Alpha-01's computed pointers before measurements are inserted
    alpha_before = await client.query_single("""
        select Sample {
            assay_count,
            measurement_count,
            total_value
        } filter .label = 'Alpha-01'
    """)
    print(f"Alpha before: assay_count={alpha_before.assay_count}, measurement_count={alpha_before.measurement_count}, total_value={alpha_before.total_value}")

    # 5. Insert Assays and Calibrations
    await client.execute("""
        insert Assay { code := 'A1', sample := (select Sample filter .label = 'Alpha-01'), value := 10.0 };
        insert Assay { code := 'A2', sample := (select Sample filter .label = 'Alpha-01'), value := 2.5 };
        insert Assay { code := 'A3', sample := (select Sample filter .label = 'Bravo-02'), value := 7.25 };
        insert Calibration { code := 'C1', sample := (select Sample filter .label = 'Alpha-01'), bias := 0.5 };
        insert Calibration { code := 'C2', sample := (select Sample filter .label = 'Charlie-03'), bias := -1.25 };
    """)
    print("Inserted Assays and Calibrations.")

    # 6. Query Alpha-01's computed pointers after measurements are inserted
    alpha_after = await client.query_single("""
        select Sample {
            assay_count,
            measurement_count,
            total_value
        } filter .label = 'Alpha-01'
    """)
    print(f"Alpha after: assay_count={alpha_after.assay_count}, measurement_count={alpha_after.measurement_count}, total_value={alpha_after.total_value}")

    # 7. Insert Certificate
    await client.execute("""
        insert Certificate { serial := 'CERT-ALPHA', sample := (select Sample filter .label = 'Alpha-01') };
    """)
    print("Inserted Certificate.")

    # 8. Insert Batch
    await client.execute("""
        insert Batch {
            code := 'BATCH-1',
            samples := (
                select Sample {
                    @position := 1
                } filter .label = 'Alpha-01'
            ) union (
                select Sample {
                    @position := 2
                } filter .label = 'Bravo-02'
            ) union (
                select Sample {
                    @position := 3
                } filter .label = 'Charlie-03'
            )
        }
    """)
    print("Inserted Batch.")

    # 9. Query Delta-04 before update
    delta_before = await client.query_single("""
        select Sample {
            label_key,
            intake_ref,
            intake_at
        } filter .label = 'Delta-04'
    """)
    print(f"Delta-04 before: key={delta_before.label_key}, ref={delta_before.intake_ref}, at={delta_before.intake_at}")

    # 10. Update Delta-04 to Zulu-99
    zulu_after = await client.query_single("""
        update Sample filter .label = 'Delta-04' set {
            label := 'Zulu-99',
            grams := 9.0
        } {
            label,
            label_key,
            intake_ref,
            intake_at
        }
    """)
    print(f"Zulu-99 after: label={zulu_after.label}, key={zulu_after.label_key}, ref={zulu_after.intake_ref}, at={zulu_after.intake_at}")

    # 11. Read age difference matches intake difference
    age_diff_match = await client.query_single("""
        with
            alpha := (select Sample filter .label = 'Alpha-01'),
            echo := (select Sample filter .label = 'Echo-05')
        select
            alpha.age - echo.age = echo.intake_at - alpha.intake_at
    """)
    print(f"Age difference matches intake difference: {age_diff_match}")

    await client.aclose()

asyncio.run(main())

